    "yearly_analysis.env_methodology_base_note": "Umweltindikatoren werden aus der offiziellen Schweizer API auf Basis von Mobitool-Faktoren abgeleitet. Die Ergebnisse sollten als standardisierte vergleichende lebenszyklusbasierte Indikatoren interpretiert werden. Für die Jahresanalyse werden Emissionen proportional zur aggregierten Jahresdistanz über alle Wetterszenarien skaliert.",
    "yearly_analysis.env_methodology_diesel_heating_note": "Für den E-Bus-Fall mit Dieselheizung liefert der Emissions-Endpunkt der Jahresanalyse ein Mischfallergebnis aus einem elektrischen Anteil und einem Dieselheizungsbeitrag. Die hier gezeigte E-Bus-Gesamtsumme ist die Summe dieser beiden Beiträge.",
    "yearly_analysis.env_methodology_diesel_heating_caveat": "Methodischer Hinweis: Für den Fall mit Dieselheizung werden Emissionen als Summe einer elektrischen Komponente und einer Dieselheizungskomponente dargestellt. Diese Mischfall-Zerlegung vermeidet die doppelte Zählung der Heizung und wird unten als Zerlegung des gesamten E-Bus-Ergebnisses angezeigt.",
