    "yearly_analysis.lifecycle_phases_exclude_dh": "Die Lebenszyklusphasen des E-Bus werden der elektrischen Seite mittels Mobitool-Phasenanteilen zugeordnet. Dieselheizungsemissionen werden separat ausgewiesen und keiner einzelnen Lebenszyklusphase zugeordnet.",
