    "yearly_analysis.electric_inputs_applied_note": "Die Neuberechnung des elektrischen Anteils der Dieselheizung fragt den Endpunkt für Fahrzeug-Umweltauswirkungen mit der in kWh/100km umgerechneten jährlichen elektrischen Energie des Diesel-Falls ab und übergibt zusätzlich gespeicherte Batterieenergie und Anzahl Batteriewechsel, sofern diese Eingaben verfügbar sind.",
